# flake8: noqa
from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class NrdrbParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        bts_id = self.enb_ent_config['id']

        if int(self.mo_num) < 10:
            self.set_parameter('nrDrbMacDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB_MAC-1')
        elif int(self.mo_num) < 15:
            self.set_parameter('nrDrbMacDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB_MAC-2')
        else:
            self.set_parameter('nrDrbMacDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB_MAC-3')

        if int(self.mo_num) < 10:
            self.set_parameter('nrDrbPdcpDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB_PDCP-1')
        elif int(self.mo_num) < 15:
            self.set_parameter('nrDrbPdcpDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB_PDCP-2')
        else:
            self.set_parameter('nrDrbPdcpDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB_PDCP-3')

        if int(self.mo_num) < 10:
            self.set_parameter('nrDrbRlcAmDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB_RLC_AM-1')
        else:
            self.set_parameter('nrDrbRlcAmDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB_RLC_AM-2')

        if int(self.mo_num) < 15:
            self.set_parameter('nrDrxDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRX-4')
        else:
            self.set_parameter('nrDrxDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRX-2')

        if int(self.mo_num) >= 15:
            self.set_parameter('maxRlcQueueingDelayGbr', '20')
            self.set_parameter('nrDrbRlcUmDN', 'MRBTS-1/NRBTS-1/NRDRB_RLC_UM-1')

        self._set_sa()

    def _set_sa(self):
        mo_num = int(self.mo_num)
        bts_id = self.enb_ent_config['id']
        self.set_parameter('actLostPduFastRetx', 'false')
        self.set_parameter('actOptDataFlowRateEst', 'true')
        # self.set_parameter('dlDataSplitMode', 'dlOverF1U')
        self.set_parameter('dscp', '0')
        # self.set_parameter('initialDLTrafficRouting', 'initDLoverX2U')

        if mo_num == 15:
            self.set_parameter('cellAggrLevel', 'Not FR1 CA eligible')
            self.set_parameter('discardTimer', '100ms')
            self.set_parameter('dlFlowControlAlgo', 'none')
            self.set_parameter('maxDataRateGbrDl', '1000')
            self.set_parameter('maxDataRateGbrUl', '1000')
            self.set_parameter('maxTransferDelayGbr', '20')
            self.set_parameter('queuingDelayDiscarding', 'Disabled')
            self.set_parameter('resType', 'GBR')
            self.set_parameter('rlcMode', 'RLC_UM')
        else:
            self.set_parameter('resType', 'nonGBR')

        if mo_num == 1:
            self.set_parameter('schedulWeight', '20')
        elif mo_num == 2:
            self.set_parameter('schedulWeight', '40')
        elif mo_num == 3:
            self.set_parameter('schedulWeight', '20')
        elif mo_num == 4:
            self.set_parameter('schedulWeight', '10')
        elif mo_num == 5:
            self.set_parameter('schedulWeight', '5')
        elif mo_num == 6:
            self.set_parameter('schedulWeight', '1')
        elif mo_num == 7:
            self.set_parameter('schedulWeight', '40')
        elif mo_num == 8:
            self.set_parameter('schedulWeight', '30')
        elif mo_num == 9:
            self.set_parameter('schedulWeight', '15')
        else:
            self.set_parameter('schedulWeight', '1')

        self.set_struct_parameter('nsaDrbParam', [
            {
                'actPrioritizeX2AfterInactivity': 'true',
                'actX2DuplicateTxNSA3x': 'false',
                'dlDataSplitBufferBuildUpThreshold': '5',
                'dlDataSplitBufferBuildUpThresholdPrioritizeX2': '5',
                'dlDataSplitGainThreshold': '5',
                'dlDataSplitMode': 'dlOverF1U',
                'dlNumOfCongOrGainDdds': '2',
                'inactivityThresholdForPrioritizeX2': '300',
                'inactivityThresholdForRestartPrioritizeX2': '100',
                'initialDLTrafficRouting': 'initDLoverX2U',
                'nsa3xBearerAllowed': 'true',
                'prioritizeX2Period': '500',
                'ulDataPath': 'ulOverNr',
                'ulDataSplitThreshold': 'infinity',
            }
        ])

